const MONTH_NAMES = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const now = new Date();

// Resolves 'July', 'July 2026', '2026-07', 'last month', and '' to one month.
// Anything it cannot read becomes null, so the caller asks rather than
// silently reporting on the wrong month.
const resolveMonth = (value) => {
  const raw = String(value ?? '').trim().toLowerCase();
  const previous = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
  if (!raw || raw === 'last month' || raw === 'previous month') {
    return { year: previous.getUTCFullYear(), monthIndex: previous.getUTCMonth() };
  }
  if (raw === 'this month' || raw === 'current month') {
    return { year: now.getUTCFullYear(), monthIndex: now.getUTCMonth() };
  }
  const explicit = /^(\d{4})-(\d{1,2})$/.exec(raw);
  if (explicit) {
    const monthIndex = Number(explicit[2]) - 1;
    if (monthIndex < 0 || monthIndex > 11) return null;
    return { year: Number(explicit[1]), monthIndex };
  }
  const named = /^([a-z]+)\s*(\d{4})?$/.exec(raw);
  if (named) {
    const monthIndex = MONTH_NAMES.findIndex((name) => name.startsWith(named[1]) && named[1].length >= 3);
    if (monthIndex === -1) return null;
    if (named[2]) return { year: Number(named[2]), monthIndex };
    // A bare month name means the most recent one that has already happened.
    const year = monthIndex > now.getUTCMonth() ? now.getUTCFullYear() - 1 : now.getUTCFullYear();
    return { year, monthIndex };
  }
  return null;
};

const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'Reading a monthly update needs a valid conversation and request ID.' };
}

const requested = String($json.month ?? '').trim();
// No month means 'whatever is newest', which is the common case.
let monthBucket = '';
if (!error && requested) {
  const resolved = resolveMonth(requested);
  if (!resolved) {
    error = { code: 'MONTH_NOT_UNDERSTOOD', message: 'Ask the user which month they mean, and pass it as a month name or as 2026-07.' };
  } else {
    const pad = (value) => String(value).padStart(2, '0');
    monthBucket = `${resolved.year}-${pad(resolved.monthIndex + 1)}-01`;
  }
}

const proposedInput = { sessionId, requestId, month: requested };
return [{ json: {
  valid: error === null,
  sessionId,
  requestId,
  monthBucket,
  proposedInput,
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const input = $('Validate Get Input').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.runId);

const candidates = input.monthBucket
  ? rows.filter((row) => String(row.monthBucket ?? '') === input.monthBucket)
  : rows;

const chosen = candidates
  .sort((a, b) => String(b.startedAt ?? '').localeCompare(String(a.startedAt ?? '')))[0] ?? null;

if (!chosen) {
  return [{ json: { ...input, hasRun: false, runId: '__none__' } }];
}

return [{ json: { ...input, hasRun: true, runId: chosen.runId, run: chosen } }];

const chosen = $('Choose Run').first().json;
const input = $('Validate Get Input').first().json;

if (!chosen.hasRun) {
  return [{ json: { ...input, response: {
    ok: true,
    hasRun: false,
    message: input.monthBucket
      ? 'There is no update for that month yet. Offer to read that month now; it takes a few minutes and costs a couple of dollars in API usage, so ask before starting.'
      : 'No monthly update has been produced yet. Offer to read last month now; it takes a few minutes and costs a couple of dollars in API usage, so ask before starting.',
  } } }];
}

const run = chosen.run;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.evidenceId);

let notes = { notes: [], unsupportedClaims: [] };
try { notes = JSON.parse(run.groundednessNotes || '{}'); } catch { notes = { notes: [], unsupportedClaims: [] }; }
let structured = {};
try { structured = JSON.parse(run.structuredJson || '{}'); } catch { structured = {}; }

const included = rows.filter((row) => String(row.includeDecision ?? '') === 'include');
const evidence = (included.length ? included : rows).slice(0, 40).map((row) => ({
  kind: row.kind,
  title: row.title,
  summary: row.summary,
  value: [row.valueText, row.unit].filter(Boolean).join(' '),
  date: row.eventDate,
  section: row.suggestedSection,
  whyItMatters: row.whyItMatters,
  emailIds: String(row.evidenceMessageIds ?? '').split(',').filter(Boolean),
  needsReview: row.needsReview === 'yes',
}));

const STATUS_MESSAGES = {
  queued: 'That run has not started reading yet. Ask again in a few minutes.',
  running: 'That run is still reading the month. Ask again in a few minutes.',
  completed: 'This is the saved update. Read it back as it is written; it is already in the founder’s voice.',
  partial: 'This update finished with something worth flagging. Read it back, and tell the user plainly which part needs checking before they send it.',
  failed: 'That run did not produce an update. Say what went wrong and offer to try again.',
};

return [{ json: { ...input, response: {
  ok: true,
  hasRun: true,
  runId: run.runId,
  status: run.status,
  monthLabel: run.monthLabel,
  audience: run.audience,
  updateText: String(run.updateText ?? ''),
  structured,
  groundednessStatus: run.groundednessStatus,
  groundednessNotes: notes.notes ?? [],
  unsupportedClaims: notes.unsupportedClaims ?? [],
  stats: {
    emailsListed: Number(run.messagesListed ?? 0),
    emailsWorthReading: Number(run.messagesAfterHeuristic ?? 0),
    threadsRead: Number(run.threadsExtracted ?? 0),
    factsFound: Number(run.evidenceExtracted ?? 0),
    factsUsed: Number(run.evidenceIncluded ?? 0),
    inputTokens: Number(run.inputTokens ?? 0),
    outputTokens: Number(run.outputTokens ?? 0),
  },
  evidence,
  errorSummary: String(run.errorSummary ?? ''),
  message: STATUS_MESSAGES[String(run.status ?? '')] ?? 'This is the saved update.',
} } }];

const input = $('Validate Get Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'get_monthly_update',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
